/**
 * Script para varrer pastas e subpastas, encontrar arquivos XLSX,
 * converter para Google Sheets temporariamente, extrair B26, M45 e D45
 * (ignorando as 2 primeiras abas) e gerar relatório sem duplicações.
 */

/*********************************
 * CONFIGURAÇÕES
 *********************************/
const PARENT_FOLDER_IDS = ['1WYH8tBnXt0zguiK2owBpDLRKPkNEmjSU' ,'18qn0o2URCmIV9xk2OWmRGEjuml21GZDH' ,'17-tgZUxbtWJ5Zay6wd8yNxA8FY6ofMqC'];
const MAX_PASTAS_POR_EXECUCAO = 20;
const TEMPO_LIMITE = 5 * 60 * 1000;
const NOME_PLANILHA_RELATORIO = "LEVANTAMENTO ATUALIZADO";


/*********************************
 * FUNÇÃO PRINCIPAL
 *********************************/
function varrerPastasRecursivamente() {
  const props = PropertiesService.getScriptProperties();
  const inicio = Date.now();
  let indiceInicio = parseInt(props.getProperty("indiceInicio")) || 0;

  const planilhaRelatorio = obterOuCriarRelatorio();
  const chavesExistentes = carregarChavesExistentes(planilhaRelatorio);

  let dadosNovos = [];
  let pastasProcessadas = 0;

  for (let i = indiceInicio; i < PARENT_FOLDER_IDS.length; i++) {
    const pastaPai = DriveApp.getFolderById(PARENT_FOLDER_IDS[i]);

    Logger.log(`📂 Explorando pasta: ${pastaPai.getName()}`);

    const arquivos = buscarArquivosXLSXRecursivo(pastaPai);
    Logger.log(`🔍 ${arquivos.length} arquivos encontrados em ${pastaPai.getName()}`);

    for (let arquivo of arquivos) {
      try {
        processarArquivoXLSX(arquivo, pastaPai, dadosNovos, chavesExistentes);
      } catch (e) {
        Logger.log(`❌ Erro ao processar ${arquivo.getName()}: ${e}`);
      }
    }

    pastasProcessadas++;

    if (Date.now() - inicio > TEMPO_LIMITE) {
      Logger.log(`⏳ Tempo limite atingido. Parando na pasta ${i + 1}/${PARENT_FOLDER_IDS.length}.`);
      props.setProperty("indiceInicio", i + 1);
      gravarRelatorio(planilhaRelatorio, dadosNovos);
      return;
    }

    if (pastasProcessadas >= MAX_PASTAS_POR_EXECUCAO) {
      Logger.log(`🧩 Lote de ${MAX_PASTAS_POR_EXECUCAO} pastas processado.`);
      props.setProperty("indiceInicio", i + 1);
      gravarRelatorio(planilhaRelatorio, dadosNovos);
      return;
    }
  }

  props.deleteProperty("indiceInicio");
  removerGatilhos("varrerPastasRecursivamente");
  Logger.log("✅ Todas as pastas e subpastas processadas.");

  gravarRelatorio(planilhaRelatorio, dadosNovos);
}


/*********************************
 * PROCESSAMENTO DE ARQUIVO XLSX
 *********************************/
function processarArquivoXLSX(arquivo, pastaPai, dadosNovos, chavesExistentes) {
  const convertido = Drive.Files.copy(
    {
      title: "TEMP_CONVERSAO_" + arquivo.getName(),
      mimeType: MimeType.GOOGLE_SHEETS
    },
    arquivo.getId()
  );

  let valorEscola = "";
  try {
    const planilhaTemp = SpreadsheetApp.openById(convertido.id);
    const abas = planilhaTemp.getSheets();

    try {
      valorEscola = abas[0].getRange("B26").getValue() || "";
    } catch (e) {
      Logger.log(`⚠️ Erro ao ler B26 da primeira aba em ${arquivo.getName()}: ${e}`);
    }

    for (let j = 2; j < abas.length; j++) {
      const aba = abas[j];

      const valorM45Raw = aba.getRange("M45").getValue();
      const valorD45Raw = aba.getRange("D45").getValue();

      const valorM45 = formatarValor(valorM45Raw);
      const valorD45 = formatarValor(valorD45Raw);

      const chave = [
        pastaPai.getName(),
        valorEscola,
        aba.getName(),
        arquivo.getName()
      ].join("||");

      if (chavesExistentes.has(chave)) continue;
      chavesExistentes.add(chave);

      dadosNovos.push([
        formatarData(new Date()),
        pastaPai.getName(),
        valorEscola,
        aba.getName(),
        valorD45 || "Não preenchido",
        valorM45 || "Não preenchido",
        arquivo.getName()
      ]);
    }

  } finally {
    try {
      Drive.Files.remove(convertido.id);
    } catch (e) {
      Logger.log(`⚠️ Falha ao remover arquivo temporário: ${e}`);
    }
  }
}


/*********************************
 * BUSCA RECURSIVA DE ARQUIVOS
 *********************************/
function buscarArquivosXLSXRecursivo(pasta) {
  let arquivos = [];

  const files = pasta.getFilesByType(MimeType.MICROSOFT_EXCEL);
  while (files.hasNext()) arquivos.push(files.next());

  const subpastas = pasta.getFolders();
  while (subpastas.hasNext()) {
    arquivos = arquivos.concat(buscarArquivosXLSXRecursivo(subpastas.next()));
  }

  return arquivos;
}


/*********************************
 * RELATÓRIO
 *********************************/
function obterOuCriarRelatorio() {
  const arquivos = DriveApp.getFilesByName(NOME_PLANILHA_RELATORIO);

  if (arquivos.hasNext()) {
    return SpreadsheetApp.open(arquivos.next());
  }

  const nova = SpreadsheetApp.create(NOME_PLANILHA_RELATORIO);
  const aba = nova.getActiveSheet();
  aba.appendRow([
    "Data Execução",
    "Pasta Pai",
    "Escola",
    "Aba",
    "Valor D45",
    "Valor M45",
    "Arquivo"
  ]);

  Logger.log(`📄 Planilha de relatório criada: ${nova.getUrl()}`);
  return nova;
}


/*********************************
 * CARREGAMENTO DE CHAVES EXISTENTES
 *********************************/
function carregarChavesExistentes(planilha) {
  const aba = planilha.getActiveSheet();
  const ultimaLinha = aba.getLastRow();
  const chaves = new Set();

  if (ultimaLinha < 2) return chaves;

  const dados = aba.getRange(2, 1, ultimaLinha - 1, aba.getLastColumn()).getValues();

  dados.forEach(linha => {
    const chave = [
      linha[1],
      linha[2],
      linha[3],
      linha[6]
    ].join("||");
    chaves.add(chave);
  });

  return chaves;
}


/*********************************
 * GRAVAR RESULTADOS
 *********************************/
function gravarRelatorio(planilha, dadosNovos) {
  if (dadosNovos.length === 0) {
    Logger.log("ℹ️ Nenhum registro novo a adicionar.");
    return;
  }

  const aba = planilha.getActiveSheet();

  aba.getRange(aba.getLastRow() + 1, 1, dadosNovos.length, dadosNovos[0].length)
     .setValues(dadosNovos);

  Logger.log(`🆕 ${dadosNovos.length} registros adicionados ao relatório.`);

  const ultimaLinha = aba.getLastRow();
  const ultimaColuna = aba.getLastColumn();

  aba.getRange(2, 1, ultimaLinha - 1, ultimaColuna)
     .sort({ column: 2, ascending: true });

  Logger.log("🔠 Relatório ordenado pela coluna 'Pasta Pai'.");
}


/*********************************
 * FORMATAR DATA → DD/MM/AAAA
 *********************************/
function formatarData(data) {
  if (!(data instanceof Date) || isNaN(data)) return "";
  const d = String(data.getDate()).padStart(2, '0');
  const m = String(data.getMonth() + 1).padStart(2, '0');
  const a = data.getFullYear();
  return `${d}/${m}/${a}`;
}


/*********************************
 * FORMATAR VALOR (data ou texto)
 *********************************/
function formatarValor(valor) {
  if (valor instanceof Date && !isNaN(valor)) {
    return formatarData(valor);
  }
  return valor !== null && valor !== undefined ? String(valor) : "";
}


/*********************************
 * REMOÇÃO DE GATILHOS
 *********************************/
function removerGatilhos(nomeFuncao) {
  ScriptApp.getProjectTriggers().forEach(g => {
    if (g.getHandlerFunction() === nomeFuncao) {
      ScriptApp.deleteTrigger(g);
      Logger.log(`🛑 Gatilho removido: ${nomeFuncao}`);
    }
  });
}

/**
 * Extrai os IDs e Nomes das subpastas de uma pasta principal
 * e os escreve em uma nova Planilha Google.
 */
function extrairIdsDeSubpastas() {
  // 1. Definição da Pasta Principal
  // SUBSTITUA "SEU_ID_VEM_AQUI" pelo ID da sua pasta principal.
  // Veja as instruções abaixo do código para saber como encontrar o ID.
  var pastaPrincipalId = ""; 

  // Verifica se o ID foi inserido. Se não, para a execução.
  if (pastaPrincipalId === "" || pastaPrincipalId === "SEU_ID_VEM_AQUI") {
    Browser.msgBox("Atenção", "Por favor, insira o ID da Pasta Principal na variável 'pastaPrincipalId' antes de executar o script.", Browser.Buttons.OK);
    return; // Interrompe a função
  }

  var nomeDaPlanilha = "IDs de Subpastas - " + new Date().toLocaleDateString("pt-BR");

  // Array para armazenar os dados: [ID, Nome]
  var dados = [];

  // Adiciona o cabeçalho
  dados.push(["ID da Subpasta", "Nome da Subpasta"]);

  try {
    var pastaPrincipal = DriveApp.getFolderById(pastaPrincipalId);
    var subpastas = pastaPrincipal.getFolders();

    // 2. Coleta dos Dados
    while (subpastas.hasNext()) {
      var subpasta = subpastas.next();
      var id = subpasta.getId();
      var nome = subpasta.getName();

      // Adiciona a linha ao array de dados
      dados.push([id, nome]);
    }

    // 3. Verificação e Criação da Planilha
    // Verifica se encontrou alguma subpasta (o array 'dados' terá mais de 1 linha, contando o cabeçalho)
    if (dados.length > 1) {
      var planilha = SpreadsheetApp.create(nomeDaPlanilha);
      var folha = planilha.getActiveSheet();

      // Move a planilha para dentro da pasta principal (por conveniência)
      var arquivoPlanilha = DriveApp.getFileById(planilha.getId());
      pastaPrincipal.addFile(arquivoPlanilha);
      DriveApp.getRootFolder().removeFile(arquivoPlanilha); // Remove da pasta raiz

      // 4. Escrita dos Dados na Planilha
      var ultimaLinha = dados.length;
      var ultimaColuna = dados[0].length; 

      // Define o intervalo onde os dados serão escritos (ex: A1:B10)
      folha.getRange(1, 1, ultimaLinha, ultimaColuna).setValues(dados);

      // 5. Formatação (Opcional)
      folha.getRange("A1:B1").setFontWeight("bold").setBackground("#cfe2f3");
      folha.autoResizeColumns(1, ultimaColuna);

      Logger.log("Planilha criada com sucesso: " + planilha.getUrl());
      Browser.msgBox("Sucesso", "Planilha criada com sucesso! Você pode acessá-la em: " + planilha.getUrl(), Browser.Buttons.OK);

    } else {
      // Se não houver subpastas, apenas informa o usuário.
      Logger.log("Nenhuma subpasta foi encontrada na pasta especificada.");
      Browser.msgBox("Informação", "Nenhuma subpasta foi encontrada na pasta com o ID fornecido. Nenhuma planilha foi criada.", Browser.Buttons.OK);
    }

  } catch (e) {
    Logger.log("Erro: " + e.toString());
    // Mensagem de erro mais amigável, comum quando o ID da pasta está errado
    if (e.message.includes("not found")) {
       Browser.msgBox("Erro", "Não foi possível encontrar a pasta. Verifique se o ID '" + pastaPrincipalId + "' está correto e se você tem permissão para acessá-la.", Browser.Buttons.OK);
    } else {
       Browser.msgBox("Erro", "Ocorreu um erro: " + e.toString(), Browser.Buttons.OK);
    }
  }
}
